extension StanceColorTokens {
    /// Builds colour tokens from a lookup by token name (for example `bg-canvas`), so a runtime
    /// can fill every role from a resolved brand theme.
    public init(role: (String) -> StanceRGBA) {
        self.init(
            bgCanvas: role("bg-canvas"),
            bgSubtle: role("bg-subtle"),
            bgMuted: role("bg-muted"),
            bgEmphasis: role("bg-emphasis"),
            bgSurface: role("bg-surface"),
            bgSurfaceRaised: role("bg-surface-raised"),
            bgOverlay: role("bg-overlay"),
            bgInverse: role("bg-inverse"),
            bgScrim: role("bg-scrim"),
            fgDefault: role("fg-default"),
            fgMuted: role("fg-muted"),
            fgSubtle: role("fg-subtle"),
            fgDisabled: role("fg-disabled"),
            fgInverse: role("fg-inverse"),
            fgLink: role("fg-link"),
            borderSubtle: role("border-subtle"),
            borderDefault: role("border-default"),
            borderStrong: role("border-strong"),
            borderControl: role("border-control"),
            borderControlHover: role("border-control-hover"),
            separator: role("separator"),
            accentBg: role("accent-bg"),
            accentBgHover: role("accent-bg-hover"),
            accentBgActive: role("accent-bg-active"),
            accentFg: role("accent-fg"),
            interactiveHover: role("interactive-hover"),
            interactiveActive: role("interactive-active"),
            interactiveSelected: role("interactive-selected"),
            interactiveSelectedFg: role("interactive-selected-fg"),
            focusRing: role("focus-ring"),
